1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Detects whether a candidate owner's email is already used by another owner,
9	 * compared case-insensitively.
10	 */
11	final class EmailDuplicates {
12	
13	    private EmailDuplicates() {
14	    }
15	
16	    /** Lower-case a value for comparison, treating null as empty. */
17	    private static String normalize(String value) {
18	        return value == null ? "" : value.toLowerCase();
19	    }
20	
21	    /** Whether an existing owner already uses the candidate's email. */
22	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
23	        String email = normalize(candidate.getEmail());
24	        if (email.isEmpty()) {
25	            return false;
26	        }
